package com.cloudticket.order.api; import com.cloudticket.order.security.OrderAuthorization; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderAuthorization authorization=new OrderAuthorization(); private final Map<String,Map<String,String>> orders=new HashMap<>(); @PostMapping public Map<String,String> create(@RequestHeader("X-User-Id")String user,@RequestBody Map<String,String> body){String id=UUID.randomUUID().toString();Map<String,String> order=new HashMap<>(body);order.put("id",id);order.put("userId",user);order.put("status","PENDING");orders.put(id,order);return order;} @GetMapping("/{id}") public ResponseEntity<?> get(@PathVariable String id,@RequestHeader("X-User-Id")String user,@RequestHeader(value="X-User-Permissions",defaultValue="")String p){Map<String,String> order=orders.get(id);if(order==null||!authorization.canRead(user,order.get("userId"),p))return ResponseEntity.notFound().build();return ResponseEntity.ok(order);} @PostMapping("/{id}/cancel") public ResponseEntity<?> cancel(@PathVariable String id,@RequestHeader("X-User-Id")String user,@RequestHeader(value="X-User-Permissions",defaultValue="")String p){Map<String,String> order=orders.get(id);if(order==null||!authorization.canWrite(user,order.get("userId"),p))return ResponseEntity.notFound().build();order.put("status","CANCELLED");return ResponseEntity.ok(order);}}
